import{_ as e,o as r,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Code Walkthroughs: Ceph Manager","description":"","frontmatter":{"title":"Ceph Code Walkthroughs: Ceph Manager","date":"2021-12-14T00:00:00.000Z","updated":"2021-12-14T00:00:00.000Z","tags":["Ceph Manager","分布式存储","代码实现","Ceph 架构","Python 模块"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Code_Walkthroughs_-_Ceph_Manager.md","filePath":"posts/2021/Ceph_Code_Walkthroughs_-_Ceph_Manager.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Code_Walkthroughs_-_Ceph_Manager.md"};function n(i,a,h,s,g,d){return r(),l("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-manager-架构与功能概述" tabindex="-1">会议主题：Ceph Manager 架构与功能概述 <a class="header-anchor" href="#会议主题-ceph-manager-架构与功能概述" aria-label="Permalink to &quot;会议主题：Ceph Manager 架构与功能概述&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Ceph Manager 的背景与目的</strong></p><ul><li>Ceph Manager 的主要目的是减轻 Ceph Monitor 的负担，特别是在大型集群中。</li><li>Manager 被设计为无状态服务，独立运行，并能根据需要将信息持久化到 Monitor 或 Rados 中。</li></ul></li><li><p><strong>Manager 的核心组件与技术栈</strong></p><ul><li>Manager 使用 C++ 和 Python 编写，核心组件类似于其他 Ceph 守护进程。</li><li>它连接到 Monitor 并订阅相关应用以获取集群信息。</li></ul></li><li><p><strong>Manager 的运行模式</strong></p><ul><li>Manager 设计为活动-备用模式，只有一个实例是活动的，负责与 Monitor 通信并发送心跳。</li><li>如果活动 Manager 停止响应，Monitor 会选择备用 Manager 成为活动实例。</li></ul></li><li><p><strong>Manager 的功能扩展</strong></p><ul><li>Manager 支持多种模块，包括预测、编排、内部集群任务以及管理长时间运行的操作。</li></ul></li><li><p><strong>Manager 的代码结构与初始化流程</strong></p><ul><li>Manager 的入口点在 <code>src/mgr/Mgr.cc</code> 文件中，遵循典型的守护进程设置流程。</li><li>Manager 初始化时会创建一个 Manager Standby 类，包含与集群通信所需的基础设施。</li></ul></li><li><p><strong>Python 模块的集成与管理</strong></p><ul><li>Manager 使用 Python 模块来扩展功能，这些模块在 Manager 启动时从磁盘加载。</li><li>Python 模块运行在自己的主线程中，使用独立的 Python 解释器。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>深入研究 Manager 的各个模块和功能细节。</li><li>探索 Manager 在处理集群统计数据和性能指标方面的优化潜力。</li><li>定期回顾和更新 Manager 的文档。</li></ul></li></ol><h4 id="会议结论" tabindex="-1">会议结论： <a class="header-anchor" href="#会议结论" aria-label="Permalink to &quot;会议结论：&quot;">​</a></h4><ul><li>本次会议对 Ceph Manager 的架构、功能和代码结构进行了全面的概述，为后续的深入研究和开发工作奠定了基础。</li></ul><h4 id="后续跟进" tabindex="-1">后续跟进： <a class="header-anchor" href="#后续跟进" aria-label="Permalink to &quot;后续跟进：&quot;">​</a></h4><ul><li>参会人员将继续关注 Manager 的开发进展，并根据需要提出进一步的问题和建议。</li></ul><h4 id="会议记录人-记录人姓名" tabindex="-1">会议记录人：[记录人姓名] <a class="header-anchor" href="#会议记录人-记录人姓名" aria-label="Permalink to &quot;会议记录人：[记录人姓名]&quot;">​</a></h4><h4 id="会议结束时间-具体时间" tabindex="-1">会议结束时间：[具体时间] <a class="header-anchor" href="#会议结束时间-具体时间" aria-label="Permalink to &quot;会议结束时间：[具体时间]&quot;">​</a></h4>',12)])])}const _=e(o,[["render",n]]);export{u as __pageData,_ as default};
